import {readPptx,importPptxPage,importSvg} from './design-import.js';
import {renderDocument} from './renderer.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createDesignImport(api){
 function open(){api.showModal('Nhập thiết kế từ Canva','PPTX / SVG · xử lý tệp trên thiết bị',`<div class="advanced-hero"><span class="live-pill">EDITABLE INTERCHANGE</span><h3>Tiếp tục thiết kế trong Luma.</h3><p>Tải thiết kế của bạn từ Canva rồi chọn tệp. Sửa các ô chữ, ảnh và vector được hỗ trợ.</p></div><div class="precision-steps"><div><b>01</b><strong>Trong Canva</strong><p>Chia sẻ → Tải xuống → PowerPoint (.pptx) nếu có; hoặc SVG.</p></div><div><b>02</b><strong>Kiểm tra tương thích</strong><p>Chọn trang, xem trước và đọc báo cáo phần chưa giữ được.</p></div><div><b>03</b><strong>Sửa từng layer</strong><p>Chỉnh chữ, ảnh và shape. Lưu .luma để giữ bản chỉnh sửa.</p></div></div><input type="file" id="design-import-file" accept=".pptx,.svg" hidden><button class="button primary" id="design-import-choose">Chọn PPTX / SVG</button> <button class="button" id="design-import-example">Mở ví dụ SVG của Luma</button><p id="design-import-status" class="advanced-status" role="status">Không cần tài khoản Luma. Tệp không gửi lên máy chủ.</p><details class="advanced-details"><summary>Canva native và độ tương thích</summary><p>Đây là nhập tệp tải xuống, không mở hoặc đồng bộ tài liệu native từ đường dẫn Canva. Canva Connect nằm ở Tệp → Canva: mở bản gốc trong Canva, lấy trang PNG về Luma và gửi ảnh trở lại. Cần cấu hình app và kết nối tài khoản; chưa có sửa cây layer native offline.</p><p>PPTX chưa dựng master/layout, bảng, biểu đồ, font nhúng, custom shape hoặc hiệu ứng phức tạp. Nhóm được trải thành layer. SVG hỗ trợ hình cơ bản, text đơn giản và path M/L/H/V/C/S/Q/T/Z; chưa có arc, clip/mask/filter/gradient hoặc tài nguyên ngoài trong bản sửa layer. Bản render PNG giữ hình được cung cấp riêng khi trình duyệt hỗ trợ. Báo cáo chỉ rõ phần bị bỏ qua. Chữ outline vẫn là vector.</p></details>`,[{label:'Đóng',run:()=>api.closeModal()}],()=>{$('#design-import-choose').onclick=()=>$('#design-import-file').click();$('#design-import-example').onclick=async()=>{try{const response=await fetch('assets/interchange-example.svg');if(!response.ok)throw Error('Không nạp được ví dụ.');const text=await response.text();await load({name:'Luma SVG example.svg',size:new Blob([text]).size,text:async()=>text});}catch(e){api.toast(e.message,true);}};$('#design-import-file').onchange=e=>{if(e.target.files?.[0])load(e.target.files[0]);};});}
 function details(result){const r=result.report;return`<div class="import-counts">${[['text','Text'],['shapes','Vector'],['images','Ảnh']].map(([k,n])=>`<span><b>${r.editable[k]}</b>${n}</span>`).join('')}<span class="${r.skipped?'is-error':''}"><b>${r.skipped}</b>Bỏ qua</span></div><p>${result.doc.width} × ${result.doc.height} px · ${result.doc.layers.length} layer</p>${r.fonts.length?'<p>Phông: '+r.fonts.map(esc).join(', ')+'</p>':''}<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`;}
 function draw(result){const c=$('#import-preview'),render=renderDocument(result.doc,api.assets,{scale:Math.min(1,1000/Math.max(result.doc.width,result.doc.height))});c.width=render.width;c.height=render.height;c.getContext('2d').drawImage(render,0,0);$('#import-report').innerHTML=details(result);}
 async function load(file){const status=$('#design-import-status');if(status)status.textContent='Đang đọc thiết kế…';try{
  if(file.size>48*1024*1024)throw Error('Chọn tệp không quá 48 MB.');
  if(/\.svg$/i.test(file.name)){const result=await importSvg(await file.text(),file.name.replace(/\.svg$/i,''),api.assets);api.showModal('Kiểm tra thiết kế',file.name,`<div class="interchange-layout"><div><canvas id="import-preview" aria-label="Thiết kế đã nhập"></canvas>${result.mergedDoc?'<label class="check-row"><input type="checkbox" id="import-show-original"> Xem bản render giữ hình (PNG)</label>':''}</div><div id="import-report" class="import-report"></div></div>`,[{label:'Hủy',run:()=>api.closeModal(true)},...result.mergedDoc?[{label:'Mở bản giữ hình',run:()=>{api.closeModal();api.setDocument(result.mergedDoc,'Nhập SVG · PNG');}}]:[],{label:result.editable===false?'Mở bản render':'Mở layer được hỗ trợ',primary:true,run:()=>{api.closeModal();api.setDocument(result.doc,'Nhập SVG');}}],()=>{draw(result);const c=$('#import-show-original');if(c)c.onchange=()=>draw({...result,doc:c.checked?result.mergedDoc:result.doc});});return;}
  if(!/\.pptx$/i.test(file.name))throw Error('Chọn .pptx hoặc .svg.');const book=await readPptx(await file.arrayBuffer()),title=file.name.replace(/\.pptx$/i,'');let current=null,mounted=true,ticket=0;
  api.showModal('Chọn trang thiết kế',`${file.name} · ${book.paths.length} trang`,`<div class="interchange-layout"><div><canvas id="import-preview" aria-label="Xem trước trang đã nhập"></canvas><p class="gen-size-note">Bản dựng từ các phần tử được hỗ trợ. Đối chiếu với thiết kế gốc nếu có cảnh báo.</p></div><div><label class="modal-field">Trang<select id="import-page">${book.paths.map((_,i)=>`<option value="${i}">Trang ${i+1}</option>`).join('')}</select></label><div id="import-report" class="import-report" role="status">Đang dựng trang…</div></div></div>`,[{label:'Hủy',run:()=>api.closeModal(true)},{label:'Mở trang này',primary:true,run:()=>{if(current){mounted=false;api.closeModal();api.setDocument(current.doc,'Nhập PPTX');}}}],()=>{const button=$('[data-modal-button="1"]');async function refresh(){const id=++ticket;button.disabled=true;current=null;$('#import-report').textContent='Đang dựng trang…';try{const result=await importPptxPage(book,Number($('#import-page').value),api.assets,{title});if(!mounted||id!==ticket)return;current=result;draw(result);button.disabled=false;}catch(e){if(mounted&&id===ticket)$('#import-report').textContent=e.message;}}$('#import-page').onchange=refresh;refresh();},()=>{mounted=false;ticket++;});
 }catch(e){if(status?.isConnected)status.textContent=e.message;else api.toast(e.message,true);}}
 return{open,load,details};
}
